boolean differentRequestor = tools.getParamAsBoolean(PropertyInfo.TYPE_TRUEFALSE, "DifferentRequestor");

try
{
	// First unlock the work object

	boolean blnStatus = tools.getDatabase().getLockManager().unlock(myStepPage, differentRequestor);

	if(!blnStatus && differentRequestor)
	{
		// lock is not released, Lock will be released when after system pulse execution is done that
	}
	else if(!blnStatus && !differentRequestor)
	{
		myStepPage.addMessage("pyUnableToUnlockWO");
	}

	if (tools.getParamAsBoolean(PropertyInfo.TYPE_TRUEFALSE, "workOnly") == false)
	{
		// Now see if there is any more unlocking that we need to do
		String strLockHandle = myStepPage.getString(".pxLockHandle");
		if (strLockHandle.length() > 0 && !strLockHandle.equals(tools.getDatabase().getHandle(myStepPage)))
		{
			String coverkey = myStepPage.getString(".pxCoverInsKey");
			if (strLockHandle.equals(coverkey))
			{
				String coverPage = tools.getParamValue("coverPage");
				if (!coverPage.equals(""))
				{
                  // Now unlock the cover
                  String coverHandle = "";
                  ClipboardPage pyWorkCover = tools.findPage(coverPage);
                 try
                    {
                   if(pyWorkCover!=null)
                   {
                     coverHandle = tools.getDatabase().getHandle(pyWorkCover);
                   }
                  }
                  catch(Exception e)
                    {
                  coverHandle = "";
                  }

					if (pyWorkCover != null && coverHandle != "" && coverkey.equals(coverHandle)) {
						blnStatus = tools.getDatabase().getLockManager().unlock(pyWorkCover, differentRequestor);
						if(!blnStatus && differentRequestor)
						{
							// lock is not released, Lock will be released when after system pulse execution is done that
						}
						else if(!blnStatus && !differentRequestor)
						{
							myStepPage.addMessage("pyUnableToUnlockCover");
						}						
					}
					else {
						blnStatus = tools.getDatabase().getLockManager().unlock(coverkey, differentRequestor);
						if(!blnStatus && differentRequestor)
						{
							// lock is not released, Lock will be released when after system pulse execution is done that
						}
						else if(!blnStatus && !differentRequestor)
						{
							myStepPage.addMessage("pyUnableToUnlockCover");
						}						
					}
				}
				else {
					blnStatus = tools.getDatabase().getLockManager().unlock(coverkey, differentRequestor);
					if(!blnStatus && differentRequestor)
					{
						// lock is not released, Lock will be released when after system pulse execution is done that
					}
					else if(!blnStatus && !differentRequestor)
					{
						myStepPage.addMessage("pyUnableToUnlockCover");
					}
				}
			}
			else
			{
				// unlock this string
				blnStatus = tools.getDatabase().getLockManager().unlock(strLockHandle, differentRequestor);
				if(!blnStatus && differentRequestor)
				{
					// lock is not released, Lock will be released when after system pulse execution is done that
				}
				else if(!blnStatus && !differentRequestor)
				{
					myStepPage.addMessage("pyUnableToUnlock\t" + strLockHandle);
				}
			}
		}

		// Last, unlock the additional handle specified
		strLockHandle = tools.getParamValue("additionalHandle");
		if (strLockHandle != null && strLockHandle.length() > 0)
		{
			blnStatus = tools.getDatabase().getLockManager().unlock(strLockHandle, differentRequestor);
			if(!blnStatus && differentRequestor)
			{
				// lock is not released, Lock will be released when after system pulse execution is done that
			}
			else if(!blnStatus && !differentRequestor)
			{
				myStepPage.addMessage("pyUnableToUnlock\t" + strLockHandle);
			}
		}
	}

} catch (DatabaseException e) {
	oLog.error(e.getMessage());
	myStepPage.addMessage(e.getMessage());
}
